gcX(){return"\u0393\u03c1\u03ac\u03c8\u03c4\u03b5 \u03c4\u03bf email \u03b5\u03b4\u03ce"},
ge7(){return"\u0395\u03b9\u03c3\u03ac\u03b3\u03b5\u03c4\u03b5 \u03c4\u03bf \u03cc\u03bd\u03bf\u03bc\u03b1"},
